			name: "an unread failure beats a running run",
			runs: []Run{sealedRun(KindScan, d, q)}, failures: []Failure{failureSeq(3)}, readThrough: 2,
			want: Progress{State: ProgressError, Percent: 50, Measured: true, Running: 1, Unread: 1},
